import java.util.HashMap;
import java.util.Map;

public class RecursionTour {
    // Trace each frame: indentation shows how deep the call stack is
    static int factorial(int n, int depth) {
        String pad = "  ".repeat(depth);
        System.out.println(pad + "factorial(" + n + ")");
        if (n <= 1) {                                   // base case
            System.out.println(pad + "-> 1");
            return 1;
        }
        int result = n * factorial(n - 1, depth + 1);   // recursive step: smaller input
        System.out.println(pad + "-> " + result);
        return result;
    }

    // Fast power: halves the exponent each call, so only O(log n) frames
    static long power(long base, int exp) {
        if (exp == 0) return 1;
        long half = power(base, exp / 2);
        return exp % 2 == 0 ? half * half : half * half * base;
    }

    static int calls = 0;
    static Map<Integer, Long> memo = new HashMap<>();

    static long fib(int n) {
        calls++;
        if (n < 2) return n;
        if (memo.containsKey(n)) return memo.get(n);
        long value = fib(n - 1) + fib(n - 2);
        memo.put(n, value);
        return value;
    }

    public static void main(String[] args) {
        System.out.println("4! = " + factorial(4, 0));
        System.out.println("2^30 = " + power(2, 30) + ", 3^13 = " + power(3, 13));
        System.out.println("fib(50) = " + fib(50) + " using " + calls + " calls thanks to memoization");
    }
}

public class RecursiveFunctions {
    static int digitSum(int n, int depth) {
        String pad = "  ".repeat(depth);
        System.out.println(pad + "digitSum(" + n + ")");
        if (n < 10) {                                       // base case: one digit
            System.out.println(pad + "returns " + n);
            return n;
        }
        int result = n % 10 + digitSum(n / 10, depth + 1);  // last digit + the rest
        System.out.println(pad + "returns " + result);
        return result;
    }

    static int sum(int[] values, int i) {
        if (i == values.length) return 0;                   // nothing left to add
        return values[i] + sum(values, i + 1);
    }

    static String reverse(String s) {
        if (s.length() <= 1) return s;
        return s.charAt(s.length() - 1) + reverse(s.substring(0, s.length() - 1));
    }

    public static void main(String[] args) {
        System.out.println("digit sum of 4096 = " + digitSum(4096, 0));
        System.out.println("sum of [3, 1, 4, 1, 5] = " + sum(new int[]{3, 1, 4, 1, 5}, 0));
        System.out.println("reverse(\"stack\") = " + reverse("stack"));
    }
}

