public class BaseCases {
    static int gcd(int a, int b) {
        if (b == 0) return a;                 // base case: remainder reached 0
        return gcd(b, a % b);
    }

    static int fib(int n) {
        if (n == 0) return 0;                 // two base cases, because the step
        if (n == 1) return 1;                 // looks back two positions
        return fib(n - 1) + fib(n - 2);
    }

    static int search(int[] a, int target, int lo, int hi) {
        if (lo > hi) return -1;               // base case 1: empty range
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) return mid;     // base case 2: found
        return a[mid] < target ? search(a, target, mid + 1, hi) : search(a, target, lo, mid - 1);
    }

    static String countdownBy2(int n) {
        if (n <= 0) return "liftoff";         // '== 0' would be skipped for odd n
        return n + " " + countdownBy2(n - 2);
    }

    static int depth = 0;
    static int noBaseCase(int n) {
        depth++;
        return noBaseCase(n + 1) + 1;          // never stops
    }

    public static void main(String[] args) {
        System.out.println("gcd(84, 36) = " + gcd(84, 36));
        System.out.println("fib(0), fib(1), fib(2), fib(5), fib(10): " + fib(0) + " " + fib(1) + " " + fib(2) + " " + fib(5) + " " + fib(10));
        int[] sorted = {1, 4, 9, 16, 25, 36};
        System.out.println("search 25 -> " + search(sorted, 25, 0, sorted.length - 1)
                + ", search 10 -> " + search(sorted, 10, 0, sorted.length - 1));
        System.out.println("countdownBy2(5): " + countdownBy2(5));
        System.out.println("countdownBy2(6): " + countdownBy2(6));
        try {
            noBaseCase(0);
        } catch (StackOverflowError e) {
            System.out.println("no base case: stack overflow caught after more than 500 frames: " + (depth > 500));
        }
    }
}

