import java.util.ArrayList;
import java.util.List;

public class Backtracking {
    static void subsets(String[] items, int start, List<String> path, List<List<String>> out) {
        System.out.println("  ".repeat(path.size()) + path);
        out.add(new ArrayList<>(path));                 // record a copy
        for (int i = start; i < items.length; i++) {
            path.add(items[i]);                         // choose
            subsets(items, i + 1, path, out);           // explore
            path.remove(path.size() - 1);               // unchoose
        }
    }

    static void permutations(String[] items, boolean[] used, List<String> path, List<String> out) {
        if (path.size() == items.length) {
            out.add(String.join("", path));
            return;
        }
        for (int i = 0; i < items.length; i++) {
            if (used[i]) continue;
            used[i] = true;                             // choose
            path.add(items[i]);
            permutations(items, used, path, out);       // explore
            path.remove(path.size() - 1);               // unchoose
            used[i] = false;
        }
    }

    public static void main(String[] args) {
        String[] items = {"a", "b", "c"};
        List<List<String>> all = new ArrayList<>();
        System.out.println("subsets, depth-first:");
        subsets(items, 0, new ArrayList<>(), all);
        System.out.println(all.size() + " subsets = 2^3");

        List<String> perms = new ArrayList<>();
        permutations(items, new boolean[items.length], new ArrayList<>(), perms);
        System.out.println("permutations: " + perms + " (" + perms.size() + " = 3!)");
    }
}

import java.util.HashMap;
import java.util.Map;

public class Memoization {
    static long calls;

    static long naiveFib(int n) {
        calls++;
        if (n < 2) return n;
        return naiveFib(n - 1) + naiveFib(n - 2);
    }

    static long memoFib(int n, long[] memo) {
        calls++;
        if (n < 2) return n;
        if (memo[n] != 0) return memo[n];                 // already computed
        memo[n] = memoFib(n - 1, memo) + memoFib(n - 2, memo);
        return memo[n];
    }

    static Map<String, Long> cache = new HashMap<>();

    static long paths(int r, int c) {
        if (r == 0 || c == 0) return 1;                    // edge cells: a single straight path
        String key = r + "," + c;
        if (cache.containsKey(key)) return cache.get(key);
        long count = paths(r - 1, c) + paths(r, c - 1);
        cache.put(key, count);
        return count;
    }

    public static void main(String[] args) {
        System.out.println(String.format("%4s %10s %12s %12s", "n", "fib(n)", "naive calls", "memo calls"));
        for (int n : new int[]{10, 20, 25}) {
            calls = 0;
            long value = naiveFib(n);
            long naiveCalls = calls;
            calls = 0;
            memoFib(n, new long[n + 1]);
            System.out.println(String.format("%4d %10d %12d %12d", n, value, naiveCalls, calls));
        }
        System.out.println("paths through a 12x12 grid: " + paths(11, 11) + " (cache entries: " + cache.size() + ")");
    }
}

