public class TreeRecursion {
    static int calls = 0;

    static int fib(int n, int depth) {
        calls++;
        System.out.println("  ".repeat(depth) + "fib(" + n + ")");
        if (n < 2) return n;
        return fib(n - 1, depth + 1) + fib(n - 2, depth + 1);   // two branches per call
    }

    static int moves = 0;

    static void hanoi(int n, char from, char to, char spare, boolean print) {
        if (n == 0) return;
        hanoi(n - 1, from, spare, to, print);     // clear the way
        moves++;
        if (print) System.out.println("  move disk " + n + " " + from + " -> " + to);
        hanoi(n - 1, spare, to, from, print);     // stack the rest on top
    }

    public static void main(String[] args) {
        int value = fib(4, 0);
        System.out.println("fib(4) = " + value + " after " + calls + " calls");

        System.out.println("Hanoi with 3 disks:");
        hanoi(3, 'A', 'C', 'B', true);
        System.out.println("  total moves: " + moves);
        for (int n : new int[]{5, 10, 20}) {
            moves = 0;
            hanoi(n, 'A', 'C', 'B', false);
            System.out.println("n=" + n + ": " + moves + " moves (2^" + n + " - 1 = " + ((1 << n) - 1) + ")");
        }
    }
}

